-- ============================================================================
--  Descrizioni dei piatti — dal menu del sito
-- ============================================================================
--
--  129 descrizioni su 225 piatti: le altre sul sito non ce l'hanno
--  (vini, distillati, birre: il nome basta).
--
--  Non servono ai calcoli. Servono a chi compone la ricetta: mentre
--  aggiunge gli ingredienti ha sotto gli occhi cosa c'e' dentro il piatto,
--  invece di andarselo a cercare sul sito e dimenticarne meta'.
--
--  Richiede la migrazione 21. Idempotente: sovrascrive e basta.
-- ============================================================================

set search_path = magazzino, public;

update magazzino.prodotto_venduto p
set descrizione = x.descrizione
from (values
  ('Alta Mora Arrigo 2022', 'Cusumano'),
  ('Altamora Etna Bianco', 'Cusumano'),
  ('Alteni di Brassica – Gaja', 'Gaja — Piemonte – Sauvignon Bianco iconico di Gaja: morbido, intenso, con aromi di frutta esotica e leggere note boisé da affinamento in barrique. Una delle più alte espressioni piemontesi del Sauvignon.'),
  ('Amarone Classico Riserva ''Costasera'' – Masi 2019', 'Masi — Uve: Corvina 70%, Rondinella 15%, Oseleta 10%, Molinara 5%. Affinato 40 mesi in rovere. Profumi intensi di frutta rossa in confettura e sotto spirito, caffè tostato e spezie. Al palato è strutturato, ricco e persistente, con tannino vellutato.'),
  ('Bao burger 1pz', 'Bao a vapore | hamburger di scottona e nobile grasso 70gr | foglia di shiso in tempura | maio al wasabi'),
  ('Bao burger spicy 1pz', 'Bao 35 gr a vapore e leggermente piastrato| burger di scottona bavarese e nobile grasso 70gr | marmellata di cipolla bianca al peperoncino fritto koreano | maio al gochujang | lattuga | salsa burger pepper spicy'),
  ('Bao burger tartufo 1pz', 'Bao a vapore 35gr | burger di scottona bavarese e nobile grasso 70gr | foglia di shiso in tempura | senape al miele e tartufo | scaglie di tartufo fresco'),
  ('Bao burger wagyu tartufo 1pz', 'Il mio primo bao anche su hio oriental ! Bao a vapore | hamburger di wagyu a5 50gr| foglia di shiso in tempura | senape al miele e tartufo | scaglie di tartufo fresco'),
  ('Bao lobster 1pz', 'Bao a vapore con hamburger di crostacei | maionese giapponese aromatizzata al lime e scorza d''arancia | julienne di lattuga | salsa teriyaki'),
